  width: calc((var(--cipher-size-icon-xs) + var(--cipher-size-icon-sm)) / 2);
  height: calc((var(--cipher-size-icon-xs) + var(--cipher-size-icon-sm)) / 2);
}
/* The trigger fills its cell, so the ring sits inside it where neighbouring cells, pinned columns and the scroll edge cannot clip it. */
.tableSort:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: calc(-1 * var(--cipher-size-focus-ring));
}
/* The overflow that truncates a cell would clip the ring of a control rendered in it, so the box
   reaches --cipher-focus-clearance past the text on every side and gives it back as negative margin.
   content-box keeps min-width and a column's maxWidth on the text, as before. */
.tableValue,
.tablePrimary {
  box-sizing: content-box;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: var(--cipher-size-cell-min);
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
}
.tablePrimary {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
  color: var(--cipher-ink);
}
.tableValue[data-mono],
.tablePrimary[data-mono] {
  font-family: var(--cipher-type-mono-font-family);
  font-size: var(--cipher-type-mono-font-size);
  line-height: var(--cipher-type-mono-line-height);
  font-weight: var(--cipher-type-mono-font-weight);
  letter-spacing: var(--cipher-type-mono-letter-spacing);
}

.treeRow > button {
  appearance: none;
  background: none;
  border: 0;
  color: inherit;
  padding: 0;
  min-width: var(--cipher-space-16);
  font: inherit;
}
.treeRow > button:focus-visible {
  outline: 2px solid var(--cipher-ink);
  outline-offset: -2px;
}

.editorActions > :global(button[data-slot="button"][data-cipher-button]) {
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
  height: auto;
}
.activityLog .titleLine {
  flex-wrap: wrap;
}
.activityLog .rowTitle {
  flex: 1 0 min(100%, 16rem);
  white-space: normal;
  overflow-wrap: anywhere;
}

.pattern {
  display: grid;
  gap: var(--cipher-space-12);
  min-width: 0;
}
.patternToolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-8);
}
.patternToolbar > span {
  margin-inline-end: auto;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-muted);
}
.patternNotice {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--cipher-space-8);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.tableScroll[data-virtual] tbody tr:not([data-spacer]) > td {
  padding-block: 0;
}
.tableScroll [data-spacer] > td {
  border: 0;
}
.tableScroll[data-virtual] .tableValue,
.tableScroll[data-virtual] .tablePrimary,
.tableScroll[data-virtual] .tableRowActions,
.tableScroll[data-virtual] .tableSelection {
  min-height: calc(var(--cipher-table-row-height, var(--cipher-size-row)) - var(--cipher-size-control-border));
  display: flex;
  align-items: center;
}
.tableScroll[data-virtual] .tableValue,
.tableScroll[data-virtual] .tablePrimary {
  display: block;
  align-content: center;
}

.nativeTable {
  --cipher-row-glyph-pull: calc((var(--cipher-size-glyph) - var(--cipher-size-target-row)) / 2);
  font-family: var(--cipher-type-body-font-family);
  font-size: var(--cipher-type-body-font-size);
  line-height: var(--cipher-type-body-line-height);
  font-weight: var(--cipher-type-body-font-weight);
  letter-spacing: var(--cipher-type-body-letter-spacing);
}
/* Row states are layers on the row's ground, so a pinned cell repaints the same stack opaquely and nothing scrolls through it. */
.nativeTableRow {
  --cipher-table-row-ground: var(--cipher-surface);
  --cipher-table-row-state: transparent;
  --cipher-table-row-hover: transparent;
  --cipher-table-row-layers:
    linear-gradient(var(--cipher-table-row-hover), var(--cipher-table-row-hover)),
    linear-gradient(var(--cipher-table-row-state), var(--cipher-table-row-state));
  background-color: var(--cipher-table-row-ground);
  background-image: var(--cipher-table-row-layers);
}
.tableScroll thead > .nativeTableRow {
  background-color: transparent;
}
.nativeTableRow:is(:hover, [data-expanded-within], [data-menu-open]):not(
    thead > *,
    [data-loading],
    [data-spacer],
    [data-row-kind],
    [data-full-width]
  ) {
  --cipher-table-row-hover: var(--cipher-hover);
}
.nativeTableRow[data-state="selected"] {
  --cipher-table-row-state: var(--cipher-selected-surface);
}
/* filter, not opacity, so the dim composes with opacity reveals inside the cells; a cell holding only text dims itself, since text has no element to filter. */
:where(tbody > .nativeTableRow > td[data-text-only], tbody > .nativeTableRow > td > *) {
  transition: filter var(--cipher-duration-moderate) var(--cipher-ease-fade);
}
/* A row that holds the focused row in a nested table, and the row it expands from, keep full strength. */
:where(
    tbody[data-has-focus]
      > .nativeTableRow:not([data-focused], [data-contains-focus], [data-focus-anchor])
  )
  > td[data-text-only]:not([data-pin], .tableActions),
:where(
    tbody[data-has-focus]
      > .nativeTableRow:not([data-focused], [data-contains-focus], [data-focus-anchor])
  )
  > td
  > * {
  filter: opacity(var(--cipher-opacity-row-dim));
}
@media (hover: hover) {
  tbody > .nativeTableRow:hover > td[data-text-only],
  tbody > .nativeTableRow:hover > td > * {
    filter: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  :where(tbody > .nativeTableRow > td[data-text-only], tbody > .nativeTableRow > td > *) {
    transition: none;
  }
}
.nativeTableHead,
.nativeTableCell {
  padding: 0 var(--cipher-space-row-inline);
  text-align: start;
  vertical-align: middle;
  white-space: nowrap;
}
.nativeTableCell {
  height: var(--cipher-table-row-height, var(--cipher-size-row));
}
.nativeTableHead {
  height: var(--cipher-size-control-md);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
  letter-spacing: var(--cipher-type-label-letter-spacing);
}
.nativeTableCaption {
  margin-top: var(--cipher-space-12);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}

.tableRowActions {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: flex-end;
  gap: var(--cipher-space-row-actions-gap);
  width: max-content;
  margin-inline-start: auto;
}
.tableRowActionSlot {
  display: inline-flex;
}
th.tableActions,
td.tableActions {
  position: sticky;
  inset-inline-end: 0;
  width: calc(
    var(--cipher-size-row) + (var(--cipher-row-action-slots, 1) - 1) * var(--cipher-size-row-action-step)
  );
  padding-inline: var(--cipher-space-row-actions-inset);
  text-align: end;
  background-color: var(--cipher-surface);
  border-inline-start: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  --cipher-nested-action-height: var(--cipher-size-target-row);
}
.tableActions [data-cipher-button] {
  --cipher-action-height: min(var(--cipher-action-requested-height), var(--cipher-nested-action-height));
}
/* DataTable draws the frame edge inside the pinned cell, so the end pad clears that line too. */
.tableScroll td.tableActions {
  padding-inline-end: calc(var(--cipher-space-row-actions-inset) + var(--cipher-size-control-border));
}
.tableScroll th.tableActions {
  background-color: var(--cipher-tint);
}
td.tableActions,
.tableScroll td[data-pin="true"],
:is(td, th)[data-pin="start"] {
  background-color: var(--cipher-table-row-ground);
  background-image: var(--cipher-table-row-layers);
}
/* Pinned cells stack over scrolled cells, and pinned header cells over pinned body cells, inside the table's 4 to 6 range. */
td:is([data-pin="true"], [data-pin="start"], .tableActions) {
  z-index: 4;
}
th[data-pin="start"] {
  z-index: 6;
}
:is(td, th)[data-pin="start"] {
  position: sticky;
  inset-inline-start: var(--cipher-pin-offset, 0px);
}
.tableSelectionCell[data-pin="start"] {
  min-width: var(--cipher-size-row);
}
.tableSelectionCell[data-pin="start"] ~ [data-pin="start"] {
  --cipher-pin-offset: var(--cipher-size-row);
}
/* A pinned cell draws its column edge and DataTable's frame-pad cover as inset and outer shadows, so both stick with the cell; a table border would stay with the scrolled columns. */
:is(td, th):is([data-pin], .tableActions) {
  box-shadow: var(--cipher-pin-edge, 0 0 transparent), var(--cipher-pin-frame, 0 0 transparent);
}
:is([data-scroll-start-x] > table, [data-scroll-start-x] > .nativeTableContainer > table)
  > *
  > tr
  > [data-pin="start"][data-pin-edge] {
  --cipher-pin-edge: inset calc(-1 * var(--cipher-size-control-border)) 0 0 var(--cipher-line-soft);
  border-inline-end-color: transparent;
}
/* Pinned columns fade scrolled content into their own paint, inherited from the cell so stripe, hover, selected and the header band all match; it shows only while the scroll-edge watcher reports content past that edge. */
:is(td, th)[data-pin="start"][data-pin-edge]::before,
:is(td, th):is(.tableActions, [data-pin="true"])::before {
  content: "";
  position: absolute;
  inset-block: 0;
  width: var(--cipher-size-scroll-fade);
  pointer-events: none;
  background-color: inherit;
  background-image: inherit;
  opacity: 0;
  transition: opacity var(--cipher-duration-moderate) var(--cipher-ease-fade);
}
:is(td, th)[data-pin="start"][data-pin-edge]::before {
  inset-inline-start: 100%;
  mask-image: linear-gradient(to right, black, transparent);
}
:is(td, th):is(.tableActions, [data-pin="true"])::before {
  inset-inline-end: 100%;
  mask-image: linear-gradient(to left, black, transparent);
}
:dir(rtl):is(td, th)[data-pin="start"][data-pin-edge]::before {
  mask-image: linear-gradient(to left, black, transparent);
}
:dir(rtl):is(td, th):is(.tableActions, [data-pin="true"])::before {
  mask-image: linear-gradient(to right, black, transparent);
}
:is([data-scroll-start-x] > table, [data-scroll-start-x] > .nativeTableContainer > table)
  > *
  > tr
  > [data-pin="start"][data-pin-edge]::before,
:is([data-scroll-end-x] > table, [data-scroll-end-x] > .nativeTableContainer > table)
  > *
  > tr
  > :is(.tableActions, [data-pin="true"])::before {
  opacity: 1;
}
/* While content passes under the tail its divider moves into the cell as an inset edge; the border colour clears instead of the border so the column keeps its width. */
:is([data-scroll-end-x] > table, [data-scroll-end-x] > .nativeTableContainer > table)
  > *
  > tr
  > :is(.tableActions, [data-pin="true"]) {
  --cipher-pin-edge: inset var(--cipher-size-control-border) 0 0 var(--cipher-line-soft);
  border-inline-start-color: transparent;
}
@media (prefers-reduced-motion: reduce) {
  :is(td, th)[data-pin="start"][data-pin-edge]::before,
  :is(td, th):is(.tableActions, [data-pin="true"])::before {
    transition: none;
  }
}
/* Pinned columns are the scroll container's edges, so its own edge fade would only wash them out. */
:is(
    .tableScroll,
    .nativeTableContainer
  )[data-scroll-fade][data-scroll-start-x][data-has-start-pin] {
  --cipher-fade-x-start: 0px;
}
:is(.tableScroll, .nativeTableContainer)[data-scroll-fade][data-scroll-end-x][data-has-end-pin] {
  --cipher-fade-x-end: 0px;
}
/* A full-width cell keeps its content in the scroll container's visible width, sized from the container, so a nested table never scrolls out of view. */
:is(.tableScroll, .nativeTableContainer)[data-has-viewport-cell] {
  container-type: inline-size;
}
td[data-pin="viewport"] {
  padding: 0;
}
.viewportContent {
  position: sticky;
  inset-inline-start: 0;
  box-sizing: border-box;
  width: 100cqi;
}
th.tableSelectionCell,
td.tableSelectionCell {
  width: var(--cipher-size-row);
  padding-inline: 0;
  border-inline-end: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  background-color: var(--cipher-table-row-ground);
  background-image: var(--cipher-table-row-layers);
}
.tableSelectionCell[data-divider="false"] {
  border-inline-end: 0;
}
.tableSelectionCell > * {
  margin-inline: auto;
}
/* The frame edge draws over the cell's first pixel, so a start pad of one line centers the checkbox between that edge and the divider. */
.tableScroll .tableSelectionCell {
  padding-inline: var(--cipher-size-control-border) 0;
}
.tableScroll th.tableSelectionCell {
  background-color: var(--cipher-tint);
}
.tableRowActionSkeleton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--cipher-size-target-row);
}
.tableRowIndicators {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-row-actions-gap);
  margin-inline: auto var(--cipher-row-glyph-pull);
  color: var(--cipher-muted);
}
.tableRowIndicators > * {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--cipher-size-target-row);
  height: var(--cipher-size-target-row);
}
.tableRowIndicators svg {
  width: var(--cipher-size-glyph);
  height: var(--cipher-size-glyph);
}

.nativeTableContainer {
  overflow-x: auto;
}

.secret[data-multiline] .machine {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
